/**
 * The path-derived naming rule: filenames become the names the model sees.
 */
import { displayPath } from "./context.js";
export const NAME_PATTERN = /^[A-Za-z0-9][A-Za-z0-9_-]*$/;
/** URL path segments reserved by the server; agents cannot use them as slugs. */
export const RESERVED_SLUGS = new Set(["v1", "playground", "docs"]);
/**
 * Filenames become the names the model sees. `__` is reserved: it joins an
 * extension's namespace to its contribution (`ci__failed_jobs`), so no
 * authored name may carry it.
 */
export function validateName(ctx, kind, name, entryPath) {
    const label = {
        skill: "Skill",
        tool: "Tool",
        extension: "Extension",
        connection: "MCP connection",
        subagent: "Subagent",
        channel: "Channel",
    }[kind];
    if (!NAME_PATTERN.test(name)) {
        ctx.diagnostics.push({
            severity: "error",
            path: displayPath(ctx, entryPath),
            message: `${label} name "${name}" must match ${NAME_PATTERN}.`,
        });
        return false;
    }
    if (name.includes("__")) {
        ctx.diagnostics.push({
            severity: "error",
            path: displayPath(ctx, entryPath),
            message: `${label} name "${name}" may not contain "__"; it is reserved for extension contributions (\`<ns>__<name>\`).`,
        });
        return false;
    }
    return true;
}
